from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 plumbum','铅；用铅做的重物'],['古法语相关铅锤词形 → 英语 plumb','悬在线上的铅锤；垂直；后来也作动词']]
W=[
E('plumber','英 /ˈplʌmə/；美 /ˈplʌmər/','管道工；水暖工','以前的管道常用铅制作，做铅活的人后来专门安装、维修管道，职业名却留了下来。','经古法语 plomier，并受拉丁 plumbarius 影响，来自 plumbum 铅。看起来像 plumb + -er，但职业名本身有早期借入路线。',[['拉丁 plumbum → plumbarius','铅 → 做铅活的人'],['古法语 plomier → 英语 plumber','铅工 → 安装、修理管道的工人']],'厨房水管漏了，你请来的就是 plumber。这个职业不限于处理水龙头，也涉及建筑里的供水、排水和相关管道。材料已经可以是铜、塑料等，词里仍保留过去做铅活的痕迹。b 不发音，别读出一个额外的 /b/。','call a plumber；a qualified plumber；work as a plumber。','plumber 是职业名称；pipe 是管道，plumbing 是管道系统或安装维修工作。不要把 plumber 理解成只修铅管的人。',('We called a plumber to fix the leaking pipe under the sink.','我们叫了管道工来修水槽下面漏水的管子。'),('The plumber checked the pipes before installing the new shower.','管道工先检查了管道，再安装新的淋浴设备。'),sources=['https://www.etymonline.com/word/plumber','https://www.oxfordlearnersdictionaries.com/definition/english/plumber']),
E('plumb','/plʌm/','铅锤；垂直的；探测深度；深入探究','把重物吊在线上，线会竖直垂下；把它放进水里，又能探到多深。','来自拉丁 plumbum 铅，经过法语相关形式借入。名词铅锤发展出垂直的形容词和探测深度的动词；更远的词源未确定。',B,'墙柱是否 plumb，是看它有没有竖直立好。plumb the depths 则从用铅锤探水深，走到把问题查到底：想摸清一个人的心思或一件事的深层原因。日常阅读中，动词的深入探究义比真的用铅锤更常见。','check that something is plumb；plumb the depths of something。','plumb 竖直，level 水平；两者都可表示安装得正，但方向不同。plum 是李子，虽然同音，不能当作同一个来源。',('The builder checked that the door frame was plumb.','建筑工人检查了门框是否竖直。'),('The novel plumbs the depths of its characters’ loneliness.','这部小说深入探索了人物内心的孤独。'),sources=['https://www.etymonline.com/word/plumb','https://www.oxfordlearnersdictionaries.com/definition/english/plumb_1']),
E('plumbing','/ˈplʌmɪŋ/','管道系统；管道安装、维修工作','把供水和排水的管路接成一整套，让水能到该去的地方，也能排出去。','英语 plumb 的 -ing 名词形式。历史上涉及加铅坠、做铅活，后来用于建筑中的水管装置与安装工作。',B+[['英语 plumb + -ing → plumbing','做相关工艺的工作 → 供水排水管道及其安装维修']],'The plumbing is old 说的是这栋房子的管道系统老旧。He does plumbing 说的是他做管道安装维修工作。它通常是不可数名词，不是把每一根水管分别叫一个 plumbing。','old plumbing；indoor plumbing；plumbing repairs；do the plumbing。','pipes 是一根根管子；plumbing 把管道、接头、装置和系统功能作为整体来说。修系统的人是 plumber。',('The house is attractive, but its plumbing needs replacing.','这栋房子很漂亮，但管道系统需要更换。'),('She learned basic plumbing so she could handle simple repairs.','她学了基础管道维修，以便处理简单的修理工作。'),sources=['https://www.etymonline.com/word/plumbing','https://www.oxfordlearnersdictionaries.com/definition/english/plumbing']),
E('plummet','/ˈplʌmɪt/','急速下降；暴跌','想象铅坠往下落：下降又快又猛，而不是缓缓少一点。','古法语 plomet 是 plom 铅锤的小称形式；英语先借入名词，再产生动词。早期动词说测深，急剧下落义是后来发展的。',[['拉丁 plumbum → 古法语 plom、plomet','铅 → 铅锤、小铅坠'],['英语名词 plummet → 动词 plummet','铅锤 → 测深；后来指急速下落']],'温度、销量、支持率都可以 plummet。它带很强的速度和幅度感：图上的线像一下子往下冲。通常主语自己下降，写 Sales plummeted；如果要说某件事让销量暴跌，可以写 caused sales to plummet。','prices plummet；temperatures plummet；plummet to a new low；plummet by 30 percent。','fall 可以很平缓，plummet 强调急剧下降。to 后面说降到哪里，by 后面说降了多少，不能混读。',('Temperatures plummeted after sunset.','太阳落山后，气温骤降。'),('Ticket sales plummeted when the lead actor withdrew.','主演退出后，门票销量暴跌。'),sources=['https://www.etymonline.com/word/plummet','https://www.oxfordlearnersdictionaries.com/definition/english/plummet_1']),
E('aplomb','英 /əˈplɒm/；美 /əˈplɑːm/','沉着自信；从容不迫','像站得很正、重心很稳的人，遇到突然的麻烦也不慌，能稳稳接住。','借自法语 aplomb，由 à plomb 垂直、平衡而来；plomb 铅追溯到拉丁 plumbum。空间上的稳，转成应对事情时的稳。',[['拉丁 plumbum → 法语 plomb','铅；铅锤'],['法语 à plomb → aplomb','保持垂直、平衡 → 沉着自信'],['英语 aplomb','应对难题时的从容和把握']],'with aplomb 常跟 handle、answer、perform 连用：出了状况，你仍回答得干脆、处理得漂亮。重点不仅是表面安静，还包括一种心里有数、拿得住场面的自信。它偏书面，但新闻和人物描写中很实用。','handle something with aplomb；answer with aplomb；perform with aplomb。','calm 可以只是情绪平静；aplomb 往往还赞赏一个人在困难场合表现得自信、得体。b 不发音。',('She handled the microphone failure with aplomb and continued without it.','麦克风出了故障，她从容应对，直接继续讲了下去。'),('He answered the unexpected questions with aplomb.','面对意外的问题，他回答得沉着自信。'),sources=['https://www.etymonline.com/word/aplomb','https://www.oxfordlearnersdictionaries.com/definition/english/aplomb'])]
ROOT=dict(id='C1077',meaning='铅；铅锤',core='PLUMB = LEAD / PLUMB WEIGHT',image='一块铅可以做成管道，也可以吊在线上：管道通向 plumber，垂线通向 plumb，坠落通向 plummet，站得稳的比喻通向 aplomb。',intro='拉丁 plumbum 的本义是金属铅，更远的来源没有定论。这个词族的实用之处，在于同一件重物分出几条清楚的路径：材料与工艺、测量垂直和深度、快速下落、人的沉着。',forms='plumb、plumber、plumbing 的 b 都不发音；aplomb 的 b 也不发音。plummet 的 -et 来自法语小称形式，不是英语把 plumb 随意改几个字母。',branches=[['铅工与管道系统','plumber, plumbing'],['垂直与探到底','plumb'],['快速下落','plummet'],['沉着应对','aplomb']],contrasts='不要把水果 plum 或胖乎乎的 plump 按拼写塞进来。aplomb 和 plummet 的关系在历史来源上，不意味着今天说沉着时还必须想到下坠。',practice='The plumber checked the plumbing; the host handled a delay with aplomb.\n\n管道工检查管路系统；主持人则从容应对延误。',words=[x['word'] for x in W],exclude={})
